#include <ctype.h>
#include <errno.h>
#include <stdint.h>
#include <stdlib.h>

#include "qs/num.h"

int qs_parse_size(const char *s, size_t *out)
{
    char *end;
    if (!isdigit((unsigned char)*s))
        return 0;
    errno = 0;
    unsigned long long n = strtoull(s, &end, 10);
    if (errno)
        return 0;

    unsigned long long mult = 1;
    switch (*end) {
    case 'g':
    case 'G':
        mult = 1024ULL * 1024 * 1024;
        end++;
        break;
    case 'm':
    case 'M':
        mult = 1024ULL * 1024;
        end++;
        break;
    case 'k':
    case 'K':
        mult = 1024ULL;
        end++;
        break;
    default:
        break;
    }
    if (*end != '\0')
        return 0;
    if (n > SIZE_MAX / mult)
        return 0;
    *out = (size_t)(n * mult);
    return 1;
}
EOF
